use super::*;

/// `surface` — the SURFACES section (`epic-the-lexicographer-defines-the-applications-language`):
/// the lexicographer's roster decisions, keyed on the crate.
///
/// The verbs deliberately mirror `feature`'s — `add` / `list` / `get` / `status` / `note` / `remove` —
/// because a session that knows one should know the other, and the two sections are the same move at
/// two tiers: the director records features, the lexicographer records surfaces.
///
/// `add` MERGES by crate on the same titles-first rule features follow, so the lexicographer can lay
/// out the crates it has examined and fill in decisions one at a time. Notes are the exception and
/// append, because a note reconstructed later has lost the part that mattered.
pub(crate) fn cmd_surface(args: &Args) -> Result<(), String> {
    let sub = args.positional.get(1).map(String::as_str).unwrap_or("");
    let s = open_store(&args.db)?;
    match sub {
        "add" => {
            let krate = args
                .positional
                .get(2)
                .ok_or("usage: bsc plan surface add <crate> [--decision keep|fold|move|split|retire] [--into <noun>] [--subject a,b] [--why <text>] [--owner <session>]")?;
            let row = crate::PlanSurface {
                krate: krate.clone(),
                decision: args.decision.clone().unwrap_or_default(),
                into: args.into.clone().filter(|v| !v.is_empty()),
                subjects: args
                    .subject
                    .as_deref()
                    .map(|v| v.split(',').map(str::trim).filter(|x| !x.is_empty()).map(str::to_string).collect())
                    .unwrap_or_default(),
                rationale: args.why.clone().filter(|v| !v.is_empty()),
                owner: args.owner.clone().filter(|v| !v.is_empty()),
                status: args.status.clone().unwrap_or_default(),
                notes: args.note.clone().filter(|v| !v.is_empty()).into_iter().collect(),
                ..Default::default()
            };
            let saved = s.surface_upsert(&row)?;
            emit_set_result(args.json, &[saved], "");
            Ok(())
        }
        "list" => {
            let all = s.surface_list()?;
            let want_status = args.status.clone();
            let want_decision = args.decision.clone();
            let rows: Vec<crate::PlanSurface> = all
                .into_iter()
                .filter(|r| want_status.as_deref().is_none_or(|w| r.status == w))
                .filter(|r| want_decision.as_deref().is_none_or(|w| r.decision == w))
                .collect();
            emit_json_or_lines(args.json, &rows, "(no surface decisions)", |_, r| render_surface_line(r));
            Ok(())
        }
        "get" => {
            let krate = args.positional.get(2).ok_or("usage: bsc plan surface get <crate>")?;
            match s.surface_get(krate)? {
                Some(r) if args.json => print_json(&serde_json::to_value(&r).unwrap_or_default(), args.pretty),
                Some(r) => print!("{}", render_surface(&r)),
                None => return Err(format!("no surface row for '{krate}'")),
            }
            Ok(())
        }
        "status" => {
            let krate = args.positional.get(2).ok_or("usage: bsc plan surface status <crate> <status>")?;
            let st = args.positional.get(3).ok_or("usage: bsc plan surface status <crate> <status>")?;
            s.surface_status(krate, st)?;
            if !args.json {
                println!("{krate} → {st}");
            }
            Ok(())
        }
        "note" => {
            let krate = args.positional.get(2).ok_or("usage: bsc plan surface note <crate> <text>")?;
            let text = args.positional.get(3).ok_or("usage: bsc plan surface note <crate> <text>")?;
            s.surface_note(krate, text)?;
            if !args.json {
                println!("{krate} + note");
            }
            Ok(())
        }
        "remove" => {
            let krate = args.positional.get(2).ok_or("usage: bsc plan surface remove <crate>")?;
            s.surface_remove(krate)?;
            if !args.json {
                println!("removed {krate}");
            }
            Ok(())
        }
        other => Err(unknown_sub(args, "surface", other)),
    }
}

/// One row as a listing line. The DECISION leads, because that is the column a reader is scanning
/// for — `bsc surface` already answers what a crate is, and this section exists to say what should
/// change about it.
pub(crate) fn render_surface_line(r: &crate::PlanSurface) -> String {
    let decision = if r.decision.is_empty() { "—" } else { &r.decision };
    let target = match (&r.into, r.subjects.is_empty()) {
        (Some(into), _) => format!(" → {into}"),
        (None, false) => format!(" ({})", r.subjects.join(", ")),
        _ => String::new(),
    };
    let owner = r.owner.as_deref().map(|o| format!("  [{o}]")).unwrap_or_default();
    format!("{:<10} {:<9} {}{}{}", r.status, decision, r.krate, target, owner)
}

/// One row in full.
pub(crate) fn render_surface(r: &crate::PlanSurface) -> String {
    let mut out = format!("{}  [{}]  {}\n", r.krate, r.status, if r.decision.is_empty() { "—" } else { &r.decision });
    if let Some(into) = &r.into {
        out.push_str(&format!("  into: {into}\n"));
    }
    if !r.subjects.is_empty() {
        out.push_str(&format!("  subjects: {}\n", r.subjects.join(", ")));
    }
    if let Some(owner) = &r.owner {
        out.push_str(&format!("  owner: {owner}\n"));
    }
    if let Some(why) = &r.rationale {
        out.push_str(&format!("  why: {why}\n"));
    }
    for n in &r.notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}
